UPDATE fields f SET description = 'Der k_i, mit dem diese Mulde in Gl. 14 und Gl. 16 rechnet. Eigenständige Versickerungsmulde: k_i der maßgeblichen Bodenschicht nach A138-05/A138-11 (die bewachsene Bodenzone ist dabei zu berücksichtigen, §6.3.2). Mulde eines Mulden-Rigolen-Elements/-Systems: k_i,BBZ der bewachsenen Bodenzone (A138-19/A138-20), weil die Rigole mit dem anstehenden Boden rechnet (§6.5.2). Serverseitig gesetzt.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'k_i_Mulde';
UPDATE fields f SET description = 'Erforderliches Speichervolumen aus der Zufluss-Versickerungs-Bilanz, Maximum über die Dauerstufen der Mulden-Bemessungshäufigkeit n_M (mit A_VA der Mulde, sonst A_VA des Projekts, sonst A_VA = A_S,m; k_i = k_i_Mulde). Das Feld V_M (Gl. 15 = A_S,m · h_M mit der gewählten Einstauhöhe) ist das VORHANDENE Volumen; die Mulde ist bemessen, wenn V_M ≥ V_M,erf (Prüfung A138-REQ-34). Serverseitig berechnet.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'V_M_erf';
