UPDATE equations e SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND e.equation_number = '24';
