UPDATE fields f SET description = 'Für die MULDE des Mulden-Rigolen-Elements ist die bewachsene Bodenzone die maßgebliche Bodenschicht (§6.5.2); die Rigole versickert mit dem k_i des anstehenden Bodens (A138-11). Erfüllt der Boden der bewachsenen Bodenzone 5.2.3.2 und liegt die Körnung im Bereich nach Bild 1, darf k_f,BBZ mit 1·10⁻⁵ bis 5·10⁻⁵ m/s angesetzt werden (Wert innerhalb des Bereichs wählen und unter Quelle „Bereich nach 5.3.3.6“ kennzeichnen — dann entfällt f_Methode); sonst gemessener Wert (f_Methode nach Tab. 11 gilt). Leer = die Mulde rechnet mit dem Projekt-k_i.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'k_f_BBZ';
UPDATE fields f SET description = 'Bestimmt, welcher Korrekturfaktor auf k_f,BBZ wirkt: Bereich nach 5.3.3.6 → nur f_Ort (f_Methode entfällt); gemessen → f_K = f_Ort·f_Methode (Gl. 6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'k_f_BBZ_quelle';
UPDATE fields f SET description = 'k_i,BBZ = k_f,BBZ · f_Ort (Bereich nach 5.3.3.6) bzw. k_f,BBZ · f_K (gemessen). Serverseitig berechnet und auf A138-17 als k_i_Mulde übernommen: die Mulde dieses Elements rechnet Gl. 14/16 und den Muldenüberlauf (Gl. 30/31) damit; die Rigole (Gl. 28/29/32) rechnet mit dem Projekt-k_i des anstehenden Bodens.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'k_i_BBZ';
