UPDATE fields f SET description = 'Q_MÜ = A_C · 10⁻⁴ · r_MÜ − A_VA · k_i · 1000 per Gl. 31.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'Q_MUE';
UPDATE fields f SET description = 'Smallest D for which V_MÜ > 0 in Gl. 30.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'r_MUE';
UPDATE fields f SET description = 'V_MÜ = [(A_C + A_VA) · r_D(n_R) · 10⁻⁷ − A_S,m · k_i] · D · 60 · f_Z − V_M per Gl. 30 (iterate D). ÜBERLAUFVOLUMEN der Mulde auf der Regenspende der Rigolen-Häufigkeit n_R mit dem k_i der bewachsenen Bodenzone: die kleinste Dauerstufe mit V_MÜ > 0 liefert r_MÜ und damit den Bemessungsabfluss des Muldenüberlaufs Q_MÜ (Gl. 31). Kein Speichervolumen — das Speichervolumen des Systems ist V_MR (Gl. 26). Serverseitig berechnet; V_MÜ ≤ 0 = die Mulde läuft bei n_R nicht über (r_MÜ = Q_MÜ = 0).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'V_MUE';
UPDATE fields f SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'rainfall_table_ref';
UPDATE fields f SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'r_D_nR';
UPDATE fields f SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'n_R_MRS';
UPDATE fields f SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'Q_zu_total_MRS';
UPDATE fields f SET description = 'Speichervolumen des Mulden-Rigolen-Systems: V_MR = V_M (Mulde, A138-17) + V_R (Rigole, A138-18) — das System wird „analog zur Bemessung von Mulden-Rigolen-Elementen (siehe 6.5.2)“ bemessen; nur die Rigolenlänge nach Gl. 32 berücksichtigt zusätzlich den Drosselabfluss Q_Dr. V_MÜ (Gl. 30) ist das ÜBERLAUFVOLUMEN der Mulde für die Bemessung des Muldenüberlaufs (Q_MÜ, Gl. 31) und kein Speichervolumen. Serverseitig berechnet; wird in die Anlagen-Zusammenfassung (A138-23) übernommen.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'V_MR';
UPDATE fields f SET description = 'Für die MULDE des Mulden-Rigolen-Systems ist die bewachsene Bodenzone die maßgebliche Bodenschicht (§6.6.2 → §6.5.2); die Rigole versickert mit dem k_i des anstehenden Bodens (A138-11). Erfüllt der Boden der bewachsenen Bodenzone 5.2.3.2 und liegt die Körnung im Bereich nach Bild 1, darf k_f,BBZ mit 1·10⁻⁵ bis 5·10⁻⁵ m/s angesetzt werden (Wert innerhalb des Bereichs wählen und unter Quelle „Bereich nach 5.3.3.6“ kennzeichnen — dann entfällt f_Methode); sonst gemessener Wert (f_Methode nach Tab. 11 gilt). Leer = die Mulde rechnet mit dem Projekt-k_i.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'k_f_BBZ';
UPDATE fields f SET description = 'Bestimmt, welcher Korrekturfaktor auf k_f,BBZ wirkt: Bereich nach 5.3.3.6 → nur f_Ort (f_Methode entfällt); gemessen → f_K = f_Ort·f_Methode (Gl. 6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'k_f_BBZ_quelle';
UPDATE fields f SET description = 'k_i,BBZ = k_f,BBZ · f_Ort (Bereich nach 5.3.3.6) bzw. k_f,BBZ · f_K (gemessen). Serverseitig berechnet und auf A138-17 als k_i_Mulde übernommen: die Mulde dieses Systems rechnet Gl. 14/16 und den Muldenüberlauf (Gl. 30/31) damit; die Rigole (Gl. 32) rechnet mit dem Projekt-k_i des anstehenden Bodens.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'k_i_BBZ';
